// #region 🔖Design Diagram Node Sizing
// [👤compose📚js🗃️sketchpad💻design🔖designdiagramnodesizing](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Design%20Diagram%20Node%20Sizing)
// Dynamic node sizing: Each circle is sized from the text's bounding box so the circle
// is roughly twice as large as the label footprint, with the label centered and balanced padding.
// Text rendered at text-xs (12px) font-bold sans-serif. Font metrics are estimated.

/** Average character width (px) for 12px bold sans-serif (text-xs font-bold). */
const DESIGN_DIAGRAM_CHAR_WIDTH = 7.2;
/** Line height (px) for 12px text. */
const DESIGN_DIAGRAM_TEXT_HEIGHT = 14;
/** Minimum circle diameter (px) to maintain visual presence. */
const DESIGN_DIAGRAM_MIN_NODE_SIZE = 24;
/**
 * Padding factor applied to the text diagonal to produce ~2× text area.
 * With 1.4 the circle area is approximately 1.96× the inscribed text rectangle.
 **/
const DESIGN_DIAGRAM_PADDING_FACTOR = 1.4;

/**
 * Computes the visual circle diameter for a design diagram node from its label.
 * The returned size is the diameter of a circle roughly twice as large as the text
 * bounding box, ensuring the label is centered with balanced inner padding.
 **/
const computeDesignNodeSize = (label: string): number => {
  const textWidth = label.length * DESIGN_DIAGRAM_CHAR_WIDTH;
  const diagonal = Math.sqrt(textWidth * textWidth + DESIGN_DIAGRAM_TEXT_HEIGHT * DESIGN_DIAGRAM_TEXT_HEIGHT);
  const diameter = diagonal * DESIGN_DIAGRAM_PADDING_FACTOR;
  return Math.max(DESIGN_DIAGRAM_MIN_NODE_SIZE, Math.ceil(diameter));
};
// #endregion 🔖Design Diagram Node Sizing

/** getConnectorPositionStyle holds the data fields for a getConnectorPositionStyle record.
 **/
// [👤compose📚js🗃️sketchpad💻design🔖imports🔖panels🔖canvas🔖diagram🪨getconnectorpositionstyle](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Imports/s/Panels/s/Canvas/s/Diagram/d/i/getConnectorPositionStyle)
/**
 * Computes the position style for a connector handle on the edge of the visual circle.
 * When nodeSize < ICON_WIDTH the circle is centered inside the ICON_WIDTH container.
 * [👤compose📚js🗃️sketchpad💻design🔖canvas🔖diagram🪨getconnectorpositionstyle](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Canvas/s/Diagram/d/i/getConnectorPositionStyle)
 **/
const getConnectorPositionStyle = (connector: Connector, nodeSize: number = ICON_WIDTH): { x: number; y: number } => {
  const { t } = connector;
  if (t === undefined) {
    return { x: 0, y: 0 };
  }
  const angle = t * 2 * Math.PI;
  const nodeRadius = nodeSize / 2;
  const containerCenter = ICON_WIDTH / 2;
  return {
    x: nodeRadius * Math.sin(angle),
    y: containerCenter - nodeRadius * Math.cos(angle),
  };
};

